"use client";

import * as React from "react";
import { Pause, Play, SkipBack, SkipForward } from "lucide-react";
import { cn } from "@/lib/utils";
import { Slider } from "@/components/ui/slider";

/**
 * AudioPlayer — interactive playback controls, full or mini. Wraps a native
 * <audio> element: play / pause, scrubber with time, ±10s skip, and optional
 * prev / next track callbacks.
 */
export interface AudioPlayerProps extends React.HTMLAttributes<HTMLDivElement> {
  src: string;
  variant?: "full" | "mini";
  title?: string;
  artist?: string;
  coverSrc?: string;
  /** ±10s skip step, seconds */
  skipBy?: number;
  onPrev?: () => void;
  onNext?: () => void;
}

function fmt(t: number) {
  if (!Number.isFinite(t)) return "0:00";
  const m = Math.floor(t / 60);
  const s = Math.floor(t % 60);
  return `${m}:${s.toString().padStart(2, "0")}`;
}

const AudioPlayer = React.forwardRef<HTMLDivElement, AudioPlayerProps>(
  ({ src, variant = "full", title, artist, coverSrc, skipBy = 10, onPrev, onNext, className, ...props }, ref) => {
    const audioRef = React.useRef<HTMLAudioElement>(null);
    const [playing, setPlaying] = React.useState(false);
    const [current, setCurrent] = React.useState(0);
    const [duration, setDuration] = React.useState(0);

    const toggle = () => {
      const a = audioRef.current;
      if (!a) return;
      if (a.paused) void a.play();
      else a.pause();
    };
    const seek = (t: number) => {
      const a = audioRef.current;
      if (a) a.currentTime = Math.max(0, Math.min(duration || 0, t));
    };
    const skip = (delta: number) => seek(current + delta);

    const audio = (
      <audio
        ref={audioRef}
        src={src}
        preload="metadata"
        onPlay={() => setPlaying(true)}
        onPause={() => setPlaying(false)}
        onTimeUpdate={(e) => setCurrent(e.currentTarget.currentTime)}
        onLoadedMetadata={(e) => setDuration(e.currentTarget.duration)}
        onEnded={() => setPlaying(false)}
      />
    );

    const PlayPause = ({ size = 44 }: { size?: number }) => (
      <button
        type="button"
        onClick={toggle}
        aria-label={playing ? "Pause" : "Play"}
        className="grid shrink-0 place-items-center rounded-full bg-action text-action-foreground outline-none transition-transform hover:scale-105 focus-visible:shadow-focus"
        style={{ width: size, height: size }}
      >
        {playing ? <Pause className="size-1/3 fill-current" /> : <Play className="size-1/3 translate-x-px fill-current" />}
      </button>
    );

    // disabled:opacity-40 (not --opacity-disabled's 0.5) is a real, pre-existing
    // inconsistency — left as a literal rather than silently changing the
    // rendered value; a design call, not a rename.
    const iconBtn =
      "grid size-8 shrink-0 place-items-center rounded-full text-muted-foreground outline-none transition-colors hover:bg-muted hover:text-foreground focus-visible:text-foreground disabled:opacity-40 [&>svg]:size-4";

    if (variant === "mini") {
      const pct = duration ? (current / duration) * 100 : 0;
      return (
        <div
          ref={ref}
          className={cn(
            "relative flex w-full max-w-[360px] items-center gap-3 overflow-hidden rounded-full border border-border bg-background p-2 pl-3 font-sans",
            className,
          )}
          {...props}
        >
          {audio}
          {coverSrc ? (
            <img src={coverSrc} alt="" className="size-10 shrink-0 rounded-full object-cover" />
          ) : (
            <div className="size-10 shrink-0 rounded-full bg-muted" />
          )}
          <div className="min-w-0 flex-1">
            <p className="truncate text-label-md font-semibold text-foreground">{title ?? "Audio"}</p>
            {artist && <p className="truncate text-body-sm text-muted-foreground">{artist}</p>}
          </div>
          <button type="button" onClick={() => skip(skipBy)} aria-label={`Forward ${skipBy}s`} className={iconBtn}>
            <SkipForward />
          </button>
          <PlayPause size={36} />
          <div className="absolute inset-x-0 bottom-0 h-1 bg-muted">
            <div className="h-full bg-action transition-[width]" style={{ width: `${pct}%` }} />
          </div>
        </div>
      );
    }

    return (
      <div
        ref={ref}
        className={cn("flex w-full max-w-[360px] flex-col gap-2 font-sans", className)}
        {...props}
      >
        {audio}
        <Slider
          value={[current]}
          max={duration || 1}
          step={0.5}
          onValueChange={(vals) => seek(vals[0] ?? 0)}
          aria-label="Seek"
        />
        <div className="flex justify-between text-body-sm text-muted-foreground">
          <span>{fmt(current)}</span>
          <span>{fmt(duration)}</span>
        </div>
        <div className="mt-1 flex items-center justify-center gap-3">
          <button type="button" onClick={onPrev} disabled={!onPrev} aria-label="Previous track" className={iconBtn}>
            <SkipBack className="fill-current" />
          </button>
          <button type="button" onClick={() => skip(-skipBy)} aria-label={`Back ${skipBy}s`} className={iconBtn}>
            <SkipBack />
          </button>
          <PlayPause />
          <button type="button" onClick={() => skip(skipBy)} aria-label={`Forward ${skipBy}s`} className={iconBtn}>
            <SkipForward />
          </button>
          <button type="button" onClick={onNext} disabled={!onNext} aria-label="Next track" className={iconBtn}>
            <SkipForward className="fill-current" />
          </button>
        </div>
      </div>
    );
  },
);
AudioPlayer.displayName = "AudioPlayer";

export { AudioPlayer };

import { type ClassValue, clsx } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

// The Material type-scale utilities (`text-label-md`, `text-body-sm`, …) come
// from `fontSize` in tailwind.config.ts. Without this, tailwind-merge reads them
// as text *colours* and drops a real colour class (`text-primary-foreground`).
const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [
        {
          text: [
            "display-lg", "display-md", "display-sm",
            "headline-lg", "headline-md", "headline-sm",
            "title-lg", "title-md", "title-sm", "title-dialog",
            "label-lg", "label-md", "label-sm",
            "body-lg", "body-md", "body-sm",
          ],
        },
      ],
    },
  },
});

/** Merges Tailwind class names, resolving conflicts (clsx + tailwind-merge). */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Keeps the keyboard somewhere useful when a control removes the row it lives in.
 *
 * A remove button inside a chip or a list row destroys itself. Nothing then holds focus, so the
 * browser drops it on `<body>` and the next Tab starts again from the top of the document — a
 * keyboard user clearing three chips is sent back to the beginning after each one.
 *
 * Call this from the removing control's own handler, with the control and a selector that matches
 * one peer per removable row. The surviving peer is chosen BEFORE the removal, from document order:
 * the next row's control, or the previous one when the last row goes. It is focused once the
 * removal has actually happened — proven by the trigger having left the document, so a handler
 * that decides not to remove anything leaves focus exactly where the user put it.
 *
 * @param trigger the control that was activated
 * @param peerSelector a selector matching the equivalent control on every row, e.g. "[data-kx-remove]"
 * @param options.scope where to look for peers; defaults to the trigger's parent list or its document
 * @param options.fallback where to go when no row survives — a chip group's own input, say
 *
 * Limit: the removal is expected to commit within a microtask or the next animation frame, which is
 * what a React state update from a click does. A removal awaited behind a network call lands later
 * than that, and its focus is the caller's to manage.
 */
export function focusAfterRemoval(
  trigger: HTMLElement | null | undefined,
  peerSelector: string,
  options: { scope?: HTMLElement | null; fallback?: HTMLElement | null } = {},
): void {
  if (!trigger?.isConnected) return;
  const scope = options.scope ?? trigger.closest("ul, ol, [data-kx-removable-group]") ?? trigger.ownerDocument.body;
  const peers = Array.from(scope.querySelectorAll<HTMLElement>(peerSelector));
  const here = peers.indexOf(trigger);
  const survivor = here < 0 ? null : (peers[here + 1] ?? peers[here - 1] ?? null);
  const target = survivor ?? options.fallback ?? null;
  if (!target) return;

  const settle = () => {
    // The trigger is still there: nothing was removed, so nothing should move.
    if (trigger.isConnected) return false;
    if (target.isConnected) target.focus();
    return true;
  };
  queueMicrotask(() => {
    if (settle()) return;
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(settle);
  });
}
